    @Test
    void directObservationDeclinesDuringGrowthWarningAndRecoversAfterRelease(
            @TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
        try (Fixture fixture = new Fixture(directory)) {
            fixture.initialize();
            LmdbSailStore backing = fixture.store.getBackingStore();
            Object owner = new Object();
            LmdbSailStore.ReadAttemptLease writer = backing.registerReadAttempt(owner,
                    (kind, token, deadline, attempts, views) -> false);
            LmdbSailStore.MapGrowthToken growthToken;
            try {
                writer.markWriteIntent();
                try (LmdbSailStore.MapGrowthAttempt warning = backing.beginMapGrowthWarning(owner)) {
                    assertNotNull(warning, "fixture must obtain a real growth warning");
                    growthToken = warning.token();
                    assertTrue(backing.growthAdmissionClosed(), "the warning must close admission");
                    Future<Optional<RdfTermDomain>> observed = fixture.pool.submit(
                            () -> fixture.source.getKnownRdfTermDomain(P));
                    assertTrue(observed.get(10, TimeUnit.SECONDS).isEmpty(),
                            "optional domain evidence must decline while growth admission is closed");
                }
            } finally {
                writer.completeTransaction();
                writer.close();
            }
            backing.awaitGrowthEnd(growthToken, null);
            assertFalse(backing.growthAdmissionClosed(), "the captured growth episode must finish");
            assertEquals(Optional.of(RdfTermDomain.IRI), fixture.source.getKnownRdfTermDomain(P),
                    "a later direct observation recovers after growth admission reopens");
        }
    }

