    @Test
    void directAdmissionPreservesInterruptionAndUnexpectedRuntimeFailure(
            @TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
        try (Fixture fixture = new Fixture(directory)) {
            fixture.initialize();
            TripleStore triples = fixture.store.getBackingStore().getTripleStore();
            IllegalStateException expected = new IllegalStateException("injected real reader-admission observer");
            Thread owner = Thread.currentThread();
            int permits = triples.getTxnManager().availableOrdinaryPermits();
            triples.getTxnManager().setAdmissionObserverForTest(txn -> {
                if (Thread.currentThread() == owner) throw expected;
            });
            try {
                assertSame(expected, assertThrows(IllegalStateException.class,
                        () -> fixture.source.getKnownRdfTermDomain(P)));
                assertEquals(permits, triples.getTxnManager().availableOrdinaryPermits(),
                        "the failed native admission must return its reader permit");
            } finally {
                triples.getTxnManager().setAdmissionObserverForTest(null);
            }
            Thread.currentThread().interrupt();
            try {
                assertThrows(InterruptedSailException.class, () -> fixture.source.getKnownRdfTermDomain(P));
                assertTrue(Thread.currentThread().isInterrupted(), "the interruption remains observable");
            } finally {
                Thread.interrupted();
            }
            assertEquals(Optional.of(RdfTermDomain.IRI), fixture.source.getKnownRdfTermDomain(P));
        }
    }

    @Test
    void cleanupConflictFromStandaloneReaderIsNotTreatedAsOptionalAdmission(
            @TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
        try (Fixture fixture = new Fixture(directory)) {
            fixture.initialize();
            ValueStore values = fixture.store.getBackingStore().valueStore();
            TripleStore triples = fixture.store.getBackingStore().getTripleStore();
            TxnManager independent = new TxnManager(triples.env, TxnManager.Mode.RESET,
                    LmdbSailStore.MapResizeKind.TRIPLE_STORE);
            LmdbFrontierPlannerSettings settings = LmdbFrontierPlannerSettings.from(
                    new LmdbStoreConfig().setFrontierEstimatorMode(FrontierEstimatorMode.OFF));
            AtomicInteger retired = new AtomicInteger();
            var cleanup = new LmdbSailStore.MapResizeConflictException(LmdbSailStore.MapResizeKind.TRIPLE_STORE,
                    "real standalone reader retirement failed");
            independent.setReaderRetirementListener(() -> {
                retired.incrementAndGet();
                throw cleanup;
            });
            try {
                int permits = independent.availableOrdinaryPermits();
                var statistics = new LmdbStoreEvaluationStatistics(values, triples, null, null, null,
                        new LmdbStatementPatternCardinalitySource(values, triples), null, settings,
                        () -> false, () -> true, null, () -> null, () -> () -> { }, null,
                        QueryExecutionPolicy.DEFAULT, () -> {
                            try (TxnManager.Txn reader = independent.createReadTxn()) {
                                return null;
                            } catch (IOException failure) {
                                throw new UncheckedIOException(failure);
                            }
                        });
                AtomicReference<RuntimeException> observed = new AtomicReference<>();
                try {
                    statistics.getKnownRdfTermDomain(P);
                } catch (RuntimeException failure) {
                    observed.set(failure);
                }
                assertAll("a cleanup failure must not be mistaken for optional admission pressure",
                        () -> assertSame(cleanup, observed.get(), "the cleanup exception identity remains visible"),
                        () -> assertEquals(1, retired.get(), "a real native reader must have reached retirement"),
                        () -> assertEquals(permits, independent.availableOrdinaryPermits(),
                                "the failing listener runs after the reader permit is returned"));
            } finally {
                independent.setReaderRetirementListener(null);
                independent.close();
                settings.close();
            }
        }
    }

    private static AtomicInteger observeCurrentThreadAdmissions(TripleStore triples, ValueStore values) {
        Thread owner = Thread.currentThread();
        AtomicInteger admissions = new AtomicInteger();
        triples.getTxnManager().setAdmissionObserverForTest(txn -> {
            if (Thread.currentThread() == owner) admissions.incrementAndGet();
        });
        values.getTxnManager().setAdmissionObserverForTest(txn -> {
            if (Thread.currentThread() == owner) admissions.incrementAndGet();
        });
        return admissions;
    }

